$ErrorActionPreference='Stop'
$root=$PSScriptRoot
$compute=Import-Csv (Join-Path $root 'benchmark.csv') | Where-Object {$_.warmup -eq '0' -and $_.validation -eq 'PASS'}
$transfer=Import-Csv (Join-Path $root 'transfer-benchmark.csv') | Where-Object {$_.warmup -eq '0' -and $_.validation -eq 'PASS'}
function Get-Stats($group,$field){$v=@($group|ForEach-Object{[double]$_.$field}|Sort-Object);$n=$v.Count;if(!$n){return $null};$mean=($v|Measure-Object -Average).Average;$median=if($n%2){$v[[int][math]::Floor($n/2)]}else{($v[$n/2-1]+$v[$n/2])/2};$ss=0.0;foreach($x in $v){$ss+=($x-$mean)*($x-$mean)};$sd=if($n -gt 1){[math]::Sqrt($ss/($n-1))}else{0};$p95=$v[[math]::Ceiling(.95*$n)-1];return [pscustomobject]@{N=$n;Mean=[math]::Round($mean,4);Median=[math]::Round($median,4);StdDev=[math]::Round($sd,4);P95=[math]::Round($p95,4)}}
$summary=@();foreach($grp in ($compute|Group-Object elements,mode,gpu970_share_percent)){$first=$grp.Group[0];$s=Get-Stats $grp.Group 'total_ms';$g0=Get-Stats $grp.Group 'gpu970_ms';$g1=Get-Stats $grp.Group 'gpu750_ms';$sy=Get-Stats $grp.Group 'sync_wait_ms';$summary += [pscustomobject]@{Elements=[int]$first.elements;Mode=$first.mode;GPU970SharePercent=[int]$first.gpu970_share_percent;ValidRuns=$s.N;TotalMeanMs=$s.Mean;TotalMedianMs=$s.Median;TotalStdDevMs=$s.StdDev;TotalP95Ms=$s.P95;GPU970MedianMs=$g0.Median;GPU750MedianMs=$g1.Median;SyncWaitMedianMs=$sy.Median;TransferMs=0;Integrity='PASS'}}
$summary|Sort-Object Elements,Mode,GPU970SharePercent|Export-Csv -NoTypeInformation -Encoding UTF8 -LiteralPath (Join-Path $root 'summary-statistics.csv')
$transferSummary=@();foreach($grp in ($transfer|Group-Object elements,gpu970_share_percent)){$first=$grp.Group[0];$s=Get-Stats $grp.Group 'transfer_ms';$w=Get-Stats $grp.Group 'queue_wait_enqueue_ms';$transferSummary += [pscustomobject]@{Elements=[int]$first.elements;GPU970SharePercent=[int]$first.gpu970_share_percent;GPU750Elements=[int]$first.gpu750_elements;PayloadBytes=[int]$first.transfer_payload_bytes;HeapBytes=[int]$first.shared_heap_bytes;ValidRuns=$s.N;TransferMeanMs=$s.Mean;TransferMedianMs=$s.Median;TransferStdDevMs=$s.StdDev;TransferP95Ms=$s.P95;WaitEnqueueMedianMs=$w.Median;Integrity='PASS'}}
$transferSummary|Sort-Object Elements,GPU970SharePercent|Export-Csv -NoTypeInformation -Encoding UTF8 -LiteralPath (Join-Path $root 'transfer-summary-statistics.csv')
$decision=@();foreach($n in @(1000000,2000000,4000000,8000000)){$solo970=$summary|Where-Object{$_.Elements -eq $n -and $_.Mode -eq 'gtx970_solo'}|Select-Object -First 1;$solo750=$summary|Where-Object{$_.Elements -eq $n -and $_.Mode -eq 'gtx750_solo'}|Select-Object -First 1;$par=@($summary|Where-Object{$_.Elements -eq $n -and $_.Mode -eq 'dual_parallel'});$seqBest=$summary|Where-Object{$_.Elements -eq $n -and $_.Mode -eq 'dual_sequential'}|Sort-Object TotalMedianMs|Select-Object -First 1;$best=$par|Sort-Object TotalMedianMs|Select-Object -First 1;$ideal=if($solo970 -and $solo750){100*$solo750.TotalMedianMs/($solo970.TotalMedianMs+$solo750.TotalMedianMs)}else{$null};$tx=$transferSummary|Where-Object{$_.Elements -eq $n -and $_.GPU970SharePercent -eq $best.GPU970SharePercent}|Select-Object -First 1;$combined=if($best -and $tx){$best.TotalMedianMs+$tx.TransferMedianMs}else{$null};$decision += [pscustomobject]@{Elements=$n;GTX970SoloMedianMs=$solo970.TotalMedianMs;GTX750SoloMedianMs=$solo750.TotalMedianMs;BestParallelRatio970Percent=$best.GPU970SharePercent;BestParallelMedianMs=$best.TotalMedianMs;BestParallelP95Ms=$best.TotalP95Ms;BestSequentialRatio970Percent=$seqBest.GPU970SharePercent;BestSequentialMedianMs=$seqBest.TotalMedianMs;MeasuredIdealShareFromSoloRates=$ideal;FinalOnlyTransferMedianMs=$tx.TransferMedianMs;ParallelPlusFinalTransferMs=$combined;OutperformsGTX970ComputeOnly=($best.TotalMedianMs -lt $solo970.TotalMedianMs);OutperformsGTX970IncludingFinalTransfer=($combined -lt $solo970.TotalMedianMs)}}
$decision|Export-Csv -NoTypeInformation -Encoding UTF8 -LiteralPath (Join-Path $root 'optimization-decision.csv')
